// Settings for the outreach workflow. Change these to match your setup.
return [{
  json: {
    location_id: 'yLiKZKvk2CeI2ckIqd1L',   // the GHL sub-account (location)
    pipeline_name: 'SG - Candidates',        // the candidate pipeline in GHL
    // The URL of the "Inbound Webhook" trigger of the GHL workflow "SG - Candidate intake".
    // The course key can only READ from GHL, so n8n hands each candidate to that GHL workflow,
    // which creates the contact + opportunity and adds the tag that starts the email sequence.
    // Paste it in n8n only, never in GitHub (anyone with it could create contacts).
    ghl_webhook: 'PASTE_GHL_WEBHOOK_URL',
    // TEST MODE: every candidate's GHL contact gets YOUR inbox with a +tag
    // (e.g. you+cand12@gmail.com), so no real person is ever emailed while testing.
    // Set to '' to email candidates at their real address.
    test_inbox: 'YOUR_EMAIL@gmail.com'
  }
}];

// Find the candidate pipeline and its stage IDs in GHL (names are matched loosely).
const s = $('Settings').first().json;
const norm = t => String(t || '').toLowerCase().replace(/[^a-z0-9]/g, '');

const pipeline = ($input.first().json.pipelines || []).find(p => norm(p.name) === norm(s.pipeline_name));
if (!pipeline) throw new Error(`GHL pipeline "${s.pipeline_name}" not found. Create it in GHL (Opportunities > Pipelines) first.`);

const stages = Object.fromEntries(pipeline.stages.map(st => [norm(st.name), st.id]));
if (!stages.outreachsent) throw new Error(`The pipeline "${pipeline.name}" needs a stage called "Outreach Sent".`);

return [{
  json: {
    pipeline_id: pipeline.id,
    pipeline_name: pipeline.name,
    stages: stages,                                                       // "outreachsent" -> stage id
    stage_names: Object.fromEntries(pipeline.stages.map(st => [st.id, st.name]))  // stage id -> "Outreach Sent"
  }
}];

// Turn each newly approved shortlist row into one request for the GHL intake workflow.
const s = $('Settings').first().json;
const info = $('Find pipeline').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.id);   // empty result -> nothing to do
if (!rows.length) return [];
// Safety: never send anything until a real test inbox is filled in.
if (/YOUR_EMAIL/i.test(s.test_inbox)) throw new Error('Open the Settings node and put your own email in test_inbox first.');
if (!/^https:\/\//.test(s.ghl_webhook)) throw new Error('Open the Settings node and paste the GHL webhook URL into ghl_webhook first.');

const testEmail = candidateId => {
  const [user, domain] = s.test_inbox.split('@');
  return `${user}+cand${candidateId}@${domain}`;
};

return rows.map(r => {
  const c = r.candidates || {};
  const fullName = c.full_name || 'Candidate';
  const [first, ...rest] = fullName.split(' ');
  return {
    json: {
      shortlist_id: r.id,
      role_id: r.role_id,
      role_title: (r.roles || {}).title || '',
      candidate_id: r.candidate_id,
      name: fullName,
      // Flat fields: these are what you map in the GHL workflow ({{inboundWebhookRequest.email}} etc.)
      first_name: first,
      last_name: rest.join(' '),
      full_name: fullName,
      email: s.test_inbox ? testEmail(r.candidate_id) : c.email,
      // The role and candidate ids in the name let us sync stages back to Supabase later.
      opportunity_name: `SG - ${fullName} (role ${r.role_id}, candidate ${r.candidate_id})`,
      source: 'SG Recruiting Copilot'
    }
  };
});

// One Slack message for the whole batch instead of one per candidate.
const done = $('Prepare GHL records').all().map(i => i.json);
const byRole = {};
for (const d of done) (byRole[d.role_id] = byRole[d.role_id] || { title: d.role_title, names: [] }).names.push(d.name);

const lines = Object.entries(byRole).map(([id, r]) => `• Role #${id} (${r.title}): ${r.names.join(', ')}`);
return [{
  json: {
    text: `:incoming_envelope: *Outreach started* for ${done.length} candidate${done.length === 1 ? '' : 's'}\n` +
      lines.join('\n') +
      `\nThey are in the GHL pipeline (Outreach Sent) and the email sequence has begun. It stops automatically when they reply.`
  }
}];

// Copy pipeline stages from GHL back to Supabase, so the portal shows where each candidate is.
const info = $('Find pipeline').first().json;
const norm = t => String(t || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const GHL_TO_DB = {
  approved: 'approved', outreachsent: 'contacted', replied: 'replied', interview: 'interview',
  submittedtoclient: 'interview', placed: 'placed', notafit: 'rejected'
};

const current = new Map($('Get current stages').all().map(i => i.json).filter(r => r.role_id)
  .map(r => [`${r.role_id}-${r.candidate_id}`, r.stage]));

const changes = [];
for (const o of ($('Get SG opportunities').first().json.opportunities || [])) {
  const m = String(o.name || '').match(/role (\d+), candidate (\d+)/);
  if (!m) continue;                                         // not created by this workflow
  const stage = GHL_TO_DB[norm(info.stage_names[o.pipelineStageId])];
  const key = `${m[1]}-${m[2]}`;
  if (stage && current.has(key) && current.get(key) !== stage) {
    changes.push({ json: { role_id: Number(m[1]), candidate_id: Number(m[2]), stage: stage } });
  }
}
return changes;
